        {
            // Arrange
            var url = "https://example.com";

            // Act
            var result = NetworkIO.HttpDelete(url);

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void HttpGet_EmptyUrl_ThrowsException()
        {
            // Arrange
            var url = "";

            // Act & Assert
            Assert.Throws<HttpRequestException>(() => NetworkIO.HttpGet(url));
        }

        [Fact]
